import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

async function queryRows<T>(ctx: AssertionContext, sql: string): Promise<T[]> {
  const result = await ctx.clickhouse.query({ query: sql, format: "JSONEachRow" });
  return (await (result as any).json()) as T[];
}

export async function daily_total_matches_source(ctx: AssertionContext): Promise<AssertionResult> {
  const sourceRows = await queryRows<{ n: number }>(ctx, "SELECT count() AS n FROM analytics.raw_events");
  const rollupRows = await queryRows<{ s: number }>(ctx, "SELECT sum(event_count) AS s FROM analytics.rollup_daily");
  const sourceCount = Number(sourceRows[0]?.n ?? 0);
  const rollupCount = Number(rollupRows[0]?.s ?? 0);
  const passed = sourceCount === rollupCount;
  return {
    passed,
    message: passed ? "Daily total matches source." : `Source ${sourceCount}, rollup ${rollupCount}.`,
    details: { sourceCount, rollupCount },
  };
}

import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

import { avoidsSelectStarQueries, scanWorkspaceForHardcodedConnections } from "../../_shared/assertion-helpers";

async function queryRows<T>(ctx: AssertionContext, sql: string): Promise<T[]> {
  const result = await ctx.clickhouse.query({ query: sql, format: "JSONEachRow" });
  return (await (result as any).json()) as T[];
}

export async function hourly_or_monthly_exists(ctx: AssertionContext): Promise<AssertionResult> {
  const hourly = await queryRows<{ n: number }>(ctx, "SELECT count() AS n FROM analytics.rollup_hourly");
  const monthly = await queryRows<{ n: number }>(ctx, "SELECT count() AS n FROM analytics.rollup_monthly");
  const hasHourly = Number(hourly[0]?.n ?? 0) > 0;
  const hasMonthly = Number(monthly[0]?.n ?? 0) > 0;
  const passed = hasHourly || hasMonthly;
  return {
    passed,
    message: passed ? "At least one additional grain exists." : "Missing hourly or monthly rollup data.",
    details: { hasHourly, hasMonthly },
  };
}

export async function no_hardcoded_connection_strings(): Promise<AssertionResult> {
  return scanWorkspaceForHardcodedConnections();
}

import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

async function queryRows<T>(ctx: AssertionContext, sql: string): Promise<T[]> {
  const result = await ctx.clickhouse.query({ query: sql, format: "JSONEachRow" });
  return (await (result as any).json()) as T[];
}

export async function rollup_tables_exist(ctx: AssertionContext): Promise<AssertionResult> {
  const rows = await queryRows<{ n: number }>(
    ctx,
    "SELECT count() AS n FROM system.tables WHERE database = 'analytics' AND name IN ('rollup_hourly', 'rollup_daily', 'rollup_monthly')",
  );
  const count = Number(rows[0]?.n ?? 0);
  const passed = count >= 2;
  return {
    passed,
    message: passed ? "Rollup tables exist." : `Expected at least 2 rollup tables, got ${count}.`,
    details: { count },
  };
}

export async function rollups_have_rows(ctx: AssertionContext): Promise<AssertionResult> {
  const dailyRows = await queryRows<{ n: number }>(ctx, "SELECT count() AS n FROM analytics.rollup_daily");
  const count = Number(dailyRows[0]?.n ?? 0);
  const passed = count > 0;
  return {
    passed,
    message: passed ? "Rollups have rows." : "Rollups are empty.",
    details: { count },
  };
}

